class Temperature:
    def __init__(self, celsius):
        self.celsius = celsius

    @classmethod
    def from_fahrenheit(cls, f):
        return cls((f - 32) * 5 / 9)

t = Temperature.from_fahrenheit(212)
print(t.celsius)

class Book:
    def __init__(self, title):
        title = title

book = Book("Python Basics")
print(book.title)

class Todo:
    def __init__(self):
        self.tasks = []

    def add(self, task):
        self.tasks.append(task)

todo = Todo().add("buy bread")
print(todo.tasks)

class Wallet:
    def __init__(self):
        self.cash = 1000
    def spend(self, amount):
        self.cash -= amount
        if self.cash < 0:
            raise ValueError("Not enough cash")
w = Wallet()
try:
    w.spend(5000)
except ValueError:
    print(w.cash)

class Rectangle:
    def __init__(self, width, height):
        self.width = width
        self.height = height

    @property
    def area(self):
        return self.width * self.height

print(Rectangle(4, 5).area())

class Product:
    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return f"Product({self.name!r})"

    def __str__(self):
        return self.name

items = [Product("Tea")]
print(items[0], items)

class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    def __eq__(self, other):
        return self.name == other.name

print(Product("Tea", 15000) == Product("Tea", 12000))
print({Product("Tea", 15000)})

